(()=>{const wrapper=document.querySelector('.equipment-wrapper');if(!wrapper)return;const items=[...wrapper.querySelectorAll('.carousel__item')],pause=wrapper.querySelector('[data-equipment-action=pause]'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let index=0,paused=false;
const update=()=>{items.forEach((item,i)=>{const prev=i===(index+items.length-1)%items.length,next=i===(index+1)%items.length;item.classList.toggle('is-current',i===index);item.classList.toggle('is-previous',prev);item.classList.toggle('is-next',next);item.setAttribute('aria-hidden',String(i!==index))});wrapper.querySelector('.equipment-position').textContent=`${index+1} / ${items.length}`};
const move=step=>{index=(index+step+items.length)%items.length;update()};wrapper.querySelectorAll('[data-equipment-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.equipmentAction;if(action==='pause'){paused=!paused;if(pause){pause.textContent=paused?'Resume':'Pause';pause.setAttribute('aria-pressed',String(paused))}}else move(action==='next'?1:-1)}));wrapper.querySelector('.carousel').addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();move(event.key==='ArrowRight'?1:-1)}});
setInterval(()=>{if(!paused&&!reduced.matches&&!document.hidden&&!wrapper.matches(':hover')&&!wrapper.contains(document.activeElement))move(1)},4500);update();})();
